// گام ۱ — بررسی توکن و آماده‌کردن یک درخواست embedding برای «موضوع + تخصص هر استاد».
// فهرست candidates را پورتال با قواعد قطعی ساخته است (برای داور: عضو همان گروه، غیر از راهنما و نویسنده).
const req = $input.first().json;
if (!$env.AGENT_TOKEN || (req.headers || {})['x-agent-token'] !== $env.AGENT_TOKEN) {
  throw new Error('Unauthorized: invalid X-Agent-Token');
}
const body = req.body || {};
const candidates = Array.isArray(body.candidates) ? body.candidates : [];
const withProfile = candidates.filter((c) => String(c.expertise || '').trim());
const withoutProfile = candidates.filter((c) => !String(c.expertise || '').trim());
const query = String(body.query_text || '').slice(0, 6000);

const purpose = body.purpose === 'advisor' ? 'advisor' : 'referee';
// مسیر بازگشت نتیجه را پورتال می‌دهد؛ اگر نداد (نسخه‌ی قدیمی پورتال) همان مسیر داور
const resultPath = /^\/api\/agents\/[\w\-\/]+\/$/.test(String(body.result_path || ''))
  ? body.result_path
  : `/api/agents/referee-suggestions/${body.run_id}/result/`;

return [
  {
    json: {
      run_id: body.run_id,
      purpose,
      result_path: resultPath,
      case: body.case || {},
      query_text: query,
      // چند نامزد برتر شباهت معنایی را مدل زبانی نمره بدهد (پورتال قدیمی فقط explain_top می‌فرستاد)
      rerank_top: Math.min(20, Math.max(1, Number(body.rerank_top) || Number(body.explain_top) || 10)),
      with_profile: withProfile,
      without_profile: withoutProfile,
      embed_request: {
        model: $env.EMBEDDING_MODEL,
        input: [query, ...withProfile.map((c) => String(c.expertise))],
      },
    },
  },
];

// گام ۳ — غربال اولیه با شباهت کسینوسی embedding و ساخت درخواست «نمره‌ی تناسب» برای مدل زبانی.
// embedding فقط فهرست کوتاه را می‌سازد؛ رتبه‌بندی اصلی را عامل (مدل زبانی) در گام بعد انجام می‌دهد.
const prep = $('Prepare Candidates').first().json;
const res = $input.first().json;

if (!Array.isArray(res.data) || res.data.length !== prep.with_profile.length + 1) {
  const err = res.error;
  const detail = (err && (err.message || (typeof err === 'string' ? err : JSON.stringify(err)))) || 'پاسخ ناقص';
  return [{ json: { run_id: prep.run_id, result_path: prep.result_path, error: 'مدل embedding پاسخ نداد.', detail: String(detail).slice(0, 300) } }];
}

const vectors = res.data
  .slice()
  .sort((a, b) => (a.index || 0) - (b.index || 0))
  .map((d) => d.embedding);

function cosine(a, b) {
  let dot = 0;
  let na = 0;
  let nb = 0;
  for (let i = 0; i < a.length; i += 1) {
    dot += a[i] * b[i];
    na += a[i] * a[i];
    nb += b[i] * b[i];
  }
  return na && nb ? dot / Math.sqrt(na * nb) : 0;
}

const scored = prep.with_profile
  .map((c, i) => ({ id: c.id, name: c.name, expertise: c.expertise, similarity: Math.round(cosine(vectors[0], vectors[i + 1]) * 10000) / 10000 }))
  .sort((a, b) => b.similarity - a.similarity);

// فهرست کوتاه به ترتیب شناسه به مدل داده می‌شود تا ترتیب شباهت روی نمره‌ی مدل اثر نگذارد
const shortlist = scored.slice(0, prep.rerank_top).sort((a, b) => a.id - b.id);
const advisor = prep.purpose === 'advisor';
const system = [
  advisor
    ? 'تو عامل تطبیق استاد راهنما برای پروژه‌ی کارشناسی هستی. دانشجو هنوز موضوع مشخصی ندارد و فقط حوزه و علایقش را نوشته است.'
    : 'تو عامل تطبیق داور برای پیشنهاد پروژه‌ی کارشناسی هستی.',
  advisor
    ? 'به هر استادِ فهرست بر اساس میزان تناسب «تخصص» او با حوزه و علایق دانشجو نمره‌ای از ۰ تا ۱۰۰ بده و دلیلش را در یک جمله‌ی کوتاه فارسی بنویس.'
    : 'به هر استادِ فهرست بر اساس میزان تناسب «تخصص» او با موضوع پروژه نمره‌ای از ۰ تا ۱۰۰ بده و دلیلش را در یک جمله‌ی کوتاه فارسی بنویس.',
  'معیار نمره:',
  '۹۰ تا ۱۰۰: تخصص استاد دقیقاً همان موضوع اصلی است.',
  '۷۰ تا ۸۹: تخصص با بخش اصلی موضوع ارتباط مستقیم دارد.',
  '۴۰ تا ۶۹: ارتباط جزئی دارد یا فقط هم‌حوزه است.',
  '۰ تا ۳۹: ارتباط ناچیز است.',
  'قواعد:',
  '۱. فقط از متن «تخصص» همان استاد استفاده کن و هیچ سابقه یا ویژگی دیگری از خودت نساز. نام، جنسیت و ترتیب فهرست نباید روی نمره اثر بگذارد.',
  '۲. به همه‌ی استادان فهرست نمره بده؛ اگر ارتباط کم است، نمره‌ی کم بده و همین را صادقانه بنویس.',
  advisor
    ? '۳. درباره‌ی این‌که چه کسی باید انتخاب شود توصیه نکن؛ تصمیم با خود دانشجوست.'
    : '۳. درباره‌ی این‌که چه کسی باید انتخاب شود توصیه نکن؛ تصمیم با مدیر گروه است.',
  'خروجی فقط یک شیء JSON با همین شکل باشد:',
  '{"rankings": [{"id": <شناسه‌ی عددی استاد>, "score": <عدد صحیح ۰ تا ۱۰۰>, "reason": "<یک جمله>"}]}',
].join('\n');
const user = [
  `${advisor ? 'حوزه و علایق دانشجو' : 'موضوع پروژه'}:\n${prep.query_text.slice(0, 1500)}`,
  'استادان:',
  ...shortlist.map((c) => `- id=${c.id} | ${c.name} | تخصص: ${c.expertise}`),
].join('\n');

return [
  {
    json: {
      run_id: prep.run_id,
      result_path: prep.result_path,
      scored,
      shortlist_ids: shortlist.map((c) => c.id),
      llm_request: {
        model: $env.LLM_CHAT_MODEL,
        temperature: 0,
        stream: false,
        response_format: { type: 'json_object' },
        messages: [
          { role: 'system', content: system },
          { role: 'user', content: user },
        ],
      },
    },
  },
];

// گام ۵ — خروجی عامل: برای هر نامزد شباهت معنایی، نمره‌ی تناسب مدل (۰ تا ۱۰۰) و دلیل.
// رتبه‌ی نهایی را پورتال از روی همین نمره‌ها می‌سازد (هم‌نمره‌ها: بار کاری کمتر جلوتر).
// اگر مدل زبانی پاسخ نداد یا JSON معتبر نداد، rerank_error فرستاده می‌شود و ترتیب شباهت معنایی می‌ماند.
const prep = $('Prepare Candidates').first().json;
const rank = $('Shortlist By Similarity').first().json;
if (rank.error) {
  return [{ json: { run_id: rank.run_id, result_path: rank.result_path, result: { error: rank.error, detail: rank.detail } } }];
}

const res = $input.first().json;
const content = res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content;
const shortlisted = new Set(rank.shortlist_ids || []);
const scores = {};
const reasons = {};
let rerankError = '';
if (!shortlisted.size) {
  // نامزدی با تخصص ثبت‌شده نبود؛ چیزی برای نمره‌دادن نیست
} else if (!content) {
  const err = res.error;
  rerankError = `مدل زبانی پاسخ نداد: ${String((err && (err.message || err)) || 'پاسخ خالی').slice(0, 200)}`;
} else {
  try {
    const clean = String(content).replace(/<think>[\s\S]*?<\/think>/g, '');
    const parsed = JSON.parse(clean.slice(clean.indexOf('{'), clean.lastIndexOf('}') + 1));
    for (const r of parsed.rankings || parsed.reasons || []) {
      const id = Number(r && r.id);
      if (!shortlisted.has(id)) continue;       // مدل فقط درباره‌ی فهرست کوتاه نظر می‌دهد
      const score = Number(r.score);
      if (r.score !== null && r.score !== '' && Number.isFinite(score)) {
        scores[id] = Math.max(0, Math.min(100, Math.round(score)));
      }
      if (r.reason) reasons[id] = String(r.reason).trim().slice(0, 400);
    }
    if (!Object.keys(scores).length) rerankError = 'مدل زبانی نمره‌ای برنگرداند.';
  } catch (e) {
    rerankError = 'پاسخ مدل زبانی JSON معتبر نبود.';
  }
}

const suggestions = [
  ...rank.scored.map((c) => ({
    referee_id: c.id,
    similarity: c.similarity,
    score: c.similarity,             // سازگاری با پورتال‌های قدیمی که فقط score را می‌شناسند
    ai_score: c.id in scores ? scores[c.id] : null,
    reason: reasons[c.id] || '',
  })),
  ...prep.without_profile.map((c) => ({
    referee_id: c.id,
    similarity: null,
    score: null,
    ai_score: null,
    reason: 'زمینه‌ی تخصصی این استاد در سامانه ثبت نشده است؛ عامل نمی‌تواند تناسب او را بسنجد.',
  })),
];

const result = { suggestions, model: `${$env.EMBEDDING_MODEL} + ${$env.LLM_CHAT_MODEL}` };
if (rerankError) result.rerank_error = rerankError;
return [{ json: { run_id: rank.run_id, result_path: rank.result_path, result } }];
